//! Python-compatible text formatting.
//!
//! WitChi writes its output through Python's `str()`/`repr()` of floats, the
//! `csv` module and `json.dump(indent=4)`. This module reproduces those byte for
//! byte (verified against fixtures generated by `scripts/make_fixtures.py`).

use std::fmt::Write as _;

/// Python whitespace as used by `str.split()` / `str.strip()`
/// (`str.isspace()`: Unicode White_Space plus the ASCII separators 0x1C–0x1F).
pub fn py_isspace(c: char) -> bool {
    c.is_whitespace() || ('\u{1c}'..='\u{1f}').contains(&c)
}

/// Python `str.strip()` with no arguments.
pub fn py_strip(s: &str) -> &str {
    s.trim_matches(py_isspace)
}

/// Python `str.rstrip()` with no arguments.
pub fn py_rstrip(s: &str) -> &str {
    s.trim_end_matches(py_isspace)
}

/// Python `str.split()` with no arguments.
pub fn py_split(s: &str) -> impl Iterator<Item = &str> {
    s.split(py_isspace).filter(|w| !w.is_empty())
}

/// Python `repr(float)` (identical to `str(np.float64)` for finite values,
/// which the fixtures check): shortest round-trip digits, positional notation
/// for decimal exponents in [-4, 16), otherwise `d.ddde±XX`.
pub fn repr_f64(x: f64) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    // Rust's `{:e}` gives a shortest round-trip digit string, e.g. "-1.2345e-7",
    // but when several strings of that length round-trip it does not always
    // pick the one closest to x, as Python (dtoa mode 0) does. Re-round x
    // correctly to the same number of digits and use that if it round-trips.
    let shortest = format!("{x:e}");
    let n_sig = shortest
        .split('e')
        .next()
        .unwrap()
        .chars()
        .filter(char::is_ascii_digit)
        .count();
    let closest = format!("{:.*e}", n_sig - 1, x);
    let sci = if closest.parse::<f64>() == Ok(x) { closest } else { shortest };
    let (mantissa, exp) = sci.split_once('e').expect("LowerExp output has an exponent");
    let exp: i32 = exp.parse().expect("integer exponent");
    let (negative, mantissa) = match mantissa.strip_prefix('-') {
        Some(m) => (true, m),
        None => (false, mantissa),
    };
    let digits: String = mantissa.chars().filter(|&c| c != '.').collect();
    let ndigits = digits.len() as i32;
    let decpt = exp + 1; // position of the decimal point relative to the digits

    let mut out = String::with_capacity(24);
    if negative {
        out.push('-');
    }
    if -4 < decpt && decpt <= 16 {
        if decpt <= 0 {
            out.push_str("0.");
            for _ in 0..-decpt {
                out.push('0');
            }
            out.push_str(&digits);
        } else if decpt >= ndigits {
            out.push_str(&digits);
            for _ in 0..(decpt - ndigits) {
                out.push('0');
            }
            out.push_str(".0");
        } else {
            out.push_str(&digits[..decpt as usize]);
            out.push('.');
            out.push_str(&digits[decpt as usize..]);
        }
    } else {
        out.push_str(&digits[..1]);
        if ndigits > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        let e = decpt - 1;
        let _ = write!(out, "e{}{:02}", if e < 0 { '-' } else { '+' }, e.abs());
    }
    out
}

/// Python `format(x, f".{prec}f")`: correctly rounded, ties to even on the
/// exact binary value.
pub fn fixed(x: f64, prec: usize) -> String {
    if x.is_nan() {
        return "nan".to_string();
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf" } else { "-inf" }.to_string();
    }
    format!("{x:.prec$}")
}

/// A JSON value with Python `json` serialisation semantics.
#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    Null,
    Int(i64),
    Float(f64),
    Str(String),
    List(Vec<Json>),
    /// Insertion-ordered object.
    Obj(Vec<(String, Json)>),
}

impl Json {
    /// `json.dumps(value, indent=4)` (no trailing newline, `ensure_ascii=True`,
    /// `allow_nan=True`).
    pub fn dumps_indent4(&self) -> String {
        let mut out = String::new();
        self.write_indented(&mut out, 0);
        out
    }

    pub(crate) fn write_indented(&self, out: &mut String, level: usize) {
        match self {
            Json::Null => out.push_str("null"),
            Json::Int(i) => {
                let _ = write!(out, "{i}");
            }
            Json::Float(f) => out.push_str(&json_float(*f)),
            Json::Str(s) => json_string(out, s),
            Json::List(items) => {
                if items.is_empty() {
                    out.push_str("[]");
                    return;
                }
                out.push('[');
                for (i, item) in items.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    newline_indent(out, level + 1);
                    item.write_indented(out, level + 1);
                }
                newline_indent(out, level);
                out.push(']');
            }
            Json::Obj(members) => {
                if members.is_empty() {
                    out.push_str("{}");
                    return;
                }
                out.push('{');
                for (i, (k, v)) in members.iter().enumerate() {
                    if i > 0 {
                        out.push(',');
                    }
                    newline_indent(out, level + 1);
                    json_string(out, k);
                    out.push_str(": ");
                    v.write_indented(out, level + 1);
                }
                newline_indent(out, level);
                out.push('}');
            }
        }
    }
}

pub(crate) fn newline_indent(out: &mut String, level: usize) {
    out.push('\n');
    for _ in 0..level * 4 {
        out.push(' ');
    }
}

/// A list of floats at nesting `level`, exactly as [`Json::dumps_indent4`]
/// writes `Json::List` of `Json::Float` there (for streaming large arrays).
pub(crate) fn json_float_list(out: &mut String, values: &[f64], level: usize) {
    if values.is_empty() {
        out.push_str("[]");
        return;
    }
    out.push('[');
    for (i, &v) in values.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        newline_indent(out, level + 1);
        out.push_str(&json_float(v));
    }
    newline_indent(out, level);
    out.push(']');
}

/// Python `json` float encoding (`float.__repr__`, plus NaN/Infinity).
pub fn json_float(x: f64) -> String {
    if x.is_nan() {
        "NaN".to_string()
    } else if x.is_infinite() {
        if x > 0.0 { "Infinity" } else { "-Infinity" }.to_string()
    } else {
        repr_f64(x)
    }
}

/// Python `json` string encoding with `ensure_ascii=True`.
pub(crate) fn json_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            ' '..='~' => out.push(c),
            _ => {
                let mut buf = [0u16; 2];
                for unit in c.encode_utf16(&mut buf) {
                    let _ = write!(out, "\\u{unit:04x}");
                }
            }
        }
    }
    out.push('"');
}

/// Python `csv.writer(f, delimiter="\t")` with the default dialect:
/// QUOTE_MINIMAL, `"` quote char (doubled inside quotes), `\r\n` line ends.
pub fn tsv_row(out: &mut String, fields: &[&str]) {
    let single_empty = fields.len() == 1 && fields[0].is_empty();
    for (i, field) in fields.iter().enumerate() {
        if i > 0 {
            out.push('\t');
        }
        let needs_quotes =
            single_empty || field.chars().any(|c| matches!(c, '\t' | '"' | '\r' | '\n'));
        if needs_quotes {
            out.push('"');
            for c in field.chars() {
                if c == '"' {
                    out.push('"');
                }
                out.push(c);
            }
            out.push('"');
        } else {
            out.push_str(field);
        }
    }
    out.push_str("\r\n");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn repr_basics() {
        assert_eq!(repr_f64(0.0), "0.0");
        assert_eq!(repr_f64(-0.0), "-0.0");
        assert_eq!(repr_f64(1.0), "1.0");
        assert_eq!(repr_f64(0.1), "0.1");
        assert_eq!(repr_f64(1e16), "1e+16");
        assert_eq!(repr_f64(1e15), "1000000000000000.0");
        assert_eq!(repr_f64(1.5e-5), "1.5e-05");
        assert_eq!(repr_f64(0.0001), "0.0001");
        assert_eq!(repr_f64(123.456), "123.456");
        assert_eq!(repr_f64(f64::INFINITY), "inf");
        assert_eq!(repr_f64(f64::NAN), "nan");
    }

    #[test]
    fn json_layout() {
        let v = Json::Obj(vec![
            ("a".into(), Json::Int(3)),
            ("b".into(), Json::List(vec![Json::Float(1.0), Json::Null])),
            ("c".into(), Json::List(vec![])),
        ]);
        assert_eq!(
            v.dumps_indent4(),
            "{\n    \"a\": 3,\n    \"b\": [\n        1.0,\n        null\n    ],\n    \"c\": []\n}"
        );
    }
}

#[cfg(test)]
mod float_list_tests {
    use super::*;

    #[test]
    fn json_float_list_matches_json_tree() {
        let vals = [0.0, -0.0, 1.5, f64::NAN, f64::INFINITY, -f64::INFINITY, 1e-300, 123456789.0];
        for n in [0usize, 1, 3, vals.len()] {
            for level in 0..4 {
                let mut want = String::new();
                Json::List(vals[..n].iter().map(|&v| Json::Float(v)).collect()).write_indented(&mut want, level);
                let mut got = String::new();
                json_float_list(&mut got, &vals[..n], level);
                assert_eq!(got, want, "n {n}, level {level}");
            }
        }
    }
}
